<?php if(!defined('ABSPATH'))exit;$org=stageart_theme_org('name',get_bloginfo('name'));?></div><footer class="stageart-site-footer"><div class="stageart-container stageart-footer-inner"><div><div class="stageart-footer-name"><?php echo esc_html($org);?></div><small>舞台芸術を、もっと自由に。</small><br><small>&copy; <?php echo esc_html((string)wp_date('Y'));?></small></div><?php $social=['x'=>'X','instagram'=>'Instagram','youtube'=>'YouTube','facebook'=>'Facebook'];$links=[];foreach($social as $k=>$label){$url=stageart_theme_org($k);if($url)$links[]='<li><a href="'.esc_url($url).'" target="_blank" rel="noopener noreferrer">'.esc_html($label).'</a></li>';}if($links)echo'<ul class="stageart-footer-social">'.implode('',$links).'</ul>';?></div></footer><?php wp_footer();?></body></html>
